     "summary": "天府立言金融研究院院长曾刚表示，这一工具并非面向市场的常态化资金投放安排，而是为应对极端情景下集中赎回及其引发的跨市场风险传导而设立的风险缓冲机制。其重点不在于替代市场融资，更不在于为经营失败兜底，而在于必要时阻断“赎回—抛售—净值下跌—再赎回”的负反馈循环，守住不发生系统性金融风险的底线。",
